(function (window) {
  function JQ(items) { this.items = Array.prototype.slice.call(items || []); }
  function $(selector) {
    if (typeof selector === "function") return document.addEventListener("DOMContentLoaded", selector);
    if (selector instanceof JQ) return selector;
    if (selector === document || selector === window || selector instanceof Element) return new JQ([selector]);
    return new JQ(document.querySelectorAll(selector));
  }
  JQ.prototype.each = function (fn) { this.items.forEach(function (el, i) { fn.call(el, i, el); }); return this; };
  JQ.prototype.addClass = function (c) { return this.each(function () { this.classList.add(c); }); };
  JQ.prototype.removeClass = function (c) { return this.each(function () { this.classList.remove(c); }); };
  JQ.prototype.toggleClass = function (c, state) { return this.each(function () { this.classList.toggle(c, state); }); };
  JQ.prototype.text = function (v) { if (v === undefined) return this.items[0]?.textContent; return this.each(function () { this.textContent = v; }); };
  JQ.prototype.html = function (v) { if (v === undefined) return this.items[0]?.innerHTML; return this.each(function () { this.innerHTML = v; }); };
  JQ.prototype.val = function (v) { if (v === undefined) return this.items[0]?.value; return this.each(function () { this.value = v; }); };
  JQ.prototype.data = function (name) { return this.items[0]?.dataset[name]; };
  JQ.prototype.find = function (s) { return new JQ(this.items.flatMap(function (el) { return Array.from(el.querySelectorAll(s)); })); };
  JQ.prototype.on = function (event, selector, handler) {
    if (handler === undefined) return this.each(function () { this.addEventListener(event, selector); });
    return this.each(function () { this.addEventListener(event, function (e) { if (e.target.closest(selector)) handler.call(e.target.closest(selector), e); }); });
  };
  JQ.prototype.trigger = function (event) { return this.each(function () { event === "click" && this.click ? this.click() : this.dispatchEvent(new Event(event, { bubbles: true })); }); };
  JQ.prototype.map = function (fn) {
    var result = this.items.map(function (el, i) { return fn.call(el, i, el); });
    return { get: function () { return result; } };
  };

  function encode(data) {
    return new URLSearchParams(data).toString();
  }
  function request(options) {
    var headers = options.headers || {};
    var body = options.data;
    if (body && !(body instanceof FormData) && options.contentType !== "application/json") {
      headers["Content-Type"] = "application/x-www-form-urlencoded;charset=UTF-8";
      body = encode(body);
    }
    if (options.contentType === "application/json") headers["Content-Type"] = "application/json";
    var promise = fetch(options.url, { method: options.method || "GET", body: body, headers: headers, credentials: "same-origin" })
      .then(function (res) { return res.json().then(function (json) { if (!res.ok) throw { responseJSON: json, status: res.status }; return json; }); });
    promise.done = function (fn) { promise.then(fn); return promise; };
    promise.fail = function (fn) { promise.catch(fn); return promise; };
    return promise;
  }
  $.ajax = request;
  $.post = function (url, data) { return request({ url: url, method: "POST", data: data }); };
  $.getJSON = function (url, data, fn) {
    if (typeof data === "function") { fn = data; data = null; }
    if (data) {
      var params = Object.keys(data).map(function (k) { return encodeURIComponent(k) + "=" + encodeURIComponent(data[k]); }).join("&");
      if (url.indexOf("?") > -1) url += "&" + params; else url += "?" + params;
    }
    var p = request({ url: url, method: "GET" }); if (fn) p.then(fn); return p;
  };
  window.$ = window.jQuery = $;
})(window);
